import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"数据路径","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/configuration/data-locations.md","filePath":"zh/kimi-code-cli/configuration/data-locations.md"}`),a={name:`kimi-code-cli/configuration/data-locations.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="数据路径" tabindex="-1">数据路径 <a class="header-anchor" href="#数据路径" aria-label="Permalink to “数据路径”">​</a></h1><p>Kimi Code CLI 把所有运行时数据——配置文件、会话历史、登录凭据、诊断日志——集中存放在 <code>~/.kimi-code/</code> 下。本页帮你搞清楚每类数据在哪里、用来做什么，以及需要时怎么清理或搬迁。</p><h2 id="数据根目录" tabindex="-1">数据根目录 <a class="header-anchor" href="#数据根目录" aria-label="Permalink to “数据根目录”">​</a></h2><p>默认数据根是 <code>~/.kimi-code/</code>，在不同平台的实际路径：</p><ul><li>macOS：<code>/Users/&lt;name&gt;/.kimi-code</code></li><li>Linux：<code>/home/&lt;name&gt;/.kimi-code</code></li><li>Windows：<code>C:\\Users\\&lt;name&gt;\\.kimi-code</code></li></ul><p>如果你需要把数据目录挪到别处（比如用多个独立环境隔离不同项目的配置），设置 <code>KIMI_CODE_HOME</code> 即可：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_CODE_HOME</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.config/kimi-code&quot;</span></span></code></pre></div><p>设置后，配置、会话、日志、OAuth 凭据、Kimi 专属用户级 Skills、全局 <code>AGENTS.md</code> 等 <strong>Kimi Code 数据</strong>都会落到新路径下。<code>KIMI_CODE_HOME</code> 的完整说明见<a href="/code/docs/kimi-code-cli/configuration/env-vars.html">环境变量</a>。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p><strong>通用 <code>.agents</code> 资源</strong>仍放在真实 OS home 下，以便跨工具共享。例如，用户级通用 Skills 仍位于 <code>~/.agents/skills/</code>，而 Kimi 专属用户级 Skills 会随 <code>KIMI_CODE_HOME</code> 移动到 <code>$KIMI_CODE_HOME/skills/</code>。</p></div><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to “目录结构”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$KIMI_CODE_HOME  （默认 ~/.kimi-code）</span></span>
<span class="line"><span>├── config.toml             # 用户配置</span></span>
<span class="line"><span>├── tui.toml                # 终端界面偏好（含自动更新开关）</span></span>
<span class="line"><span>├── AGENTS.md               # 全局 Kimi 专属 Agent 指令（可选）</span></span>
<span class="line"><span>├── mcp.json                # 用户级 MCP server 声明（可选）</span></span>
<span class="line"><span>├── skills/                 # Kimi 专属用户级 Skills（可选）</span></span>
<span class="line"><span>├── plugins/</span></span>
<span class="line"><span>│   ├── installed.json      # 已安装 plugin 记录与启用状态</span></span>
<span class="line"><span>│   └── managed/            # zip/本地路径安装的 plugin 副本</span></span>
<span class="line"><span>├── session_index.jsonl     # 会话索引</span></span>
<span class="line"><span>├── credentials/            # OAuth 凭据（目录 0700，文件 0600）</span></span>
<span class="line"><span>│   ├── &lt;name&gt;.json</span></span>
<span class="line"><span>│   └── mcp/</span></span>
<span class="line"><span>│       └── &lt;key&gt;-&lt;suffix&gt;.json</span></span>
<span class="line"><span>├── sessions/               # 会话数据（详见下文）</span></span>
<span class="line"><span>│   └── &lt;workDirKey&gt;/&lt;sessionId&gt;/</span></span>
<span class="line"><span>├── bin/</span></span>
<span class="line"><span>│   ├── rg                  # Grep 使用的托管 ripgrep 二进制（Windows 为 rg.exe）</span></span>
<span class="line"><span>│   └── fd                  # 文件引用使用的托管 fd 二进制（Windows 为 fd.exe）</span></span>
<span class="line"><span>├── logs/</span></span>
<span class="line"><span>│   └── kimi-code.log       # 全局诊断日志</span></span>
<span class="line"><span>├── updates/</span></span>
<span class="line"><span>│   ├── latest.json</span></span>
<span class="line"><span>│   ├── install.json</span></span>
<span class="line"><span>│   ├── install.lock</span></span>
<span class="line"><span>│   └── rollout.log</span></span>
<span class="line"><span>└── user-history/</span></span>
<span class="line"><span>    └── &lt;md5(workDir)&gt;.jsonl</span></span></code></pre></div><h2 id="各类文件说明" tabindex="-1">各类文件说明 <a class="header-anchor" href="#各类文件说明" aria-label="Permalink to “各类文件说明”">​</a></h2><p>数据根下的顶层文件各有用途，大部分由 CLI 自动管理：</p><ul><li><strong><code>config.toml</code></strong>：主运行时配置，存放供应商、模型、循环控制等用户级设置。详见<a href="/code/docs/kimi-code-cli/configuration/config-files.html">配置文件</a>。</li><li><strong><code>tui.toml</code></strong>：终端界面客户端偏好，包括 <code>[upgrade].auto_install</code>（自动更新，默认开启）。可在 <code>/settings</code> 关闭，或手动设为 <code>auto_install = false</code>。</li><li><strong><code>AGENTS.md</code></strong>：全局 Kimi 专属 Agent 指令。该文件会随 <code>KIMI_CODE_HOME</code> 移动；跨工具通用指令仍可放在 <code>~/.agents/AGENTS.md</code>。</li><li><strong><code>mcp.json</code></strong>：用户级 MCP server 声明，启动时与项目内的 <code>.kimi-code/mcp.json</code> 合并加载。详见 <a href="/code/docs/kimi-code-cli/customization/mcp.html">MCP</a>。</li><li><strong><code>skills/</code></strong>：Kimi 专属用户级 Skills。该目录会随 <code>KIMI_CODE_HOME</code> 移动；跨工具通用 Skills 仍可放在 <code>~/.agents/skills/</code>。详见 <a href="/code/docs/kimi-code-cli/customization/skills.html">Agent Skills</a>。</li><li><strong><code>plugins/installed.json</code></strong>：记录已安装的 plugin、每个 plugin 的启用状态，以及通过 <code>/plugins</code> 或 <code>/plugins mcp disable|enable</code> 修改的 MCP server 能力状态。本地路径和 zip URL 安装的文件会复制到 <code>plugins/managed/&lt;id&gt;/</code>。详见 <a href="/code/docs/kimi-code-cli/customization/plugins.html">Plugins</a>。</li><li><strong><code>credentials/</code></strong>：OAuth 凭据目录，权限 <code>0o700</code>（目录）/ <code>0o600</code>（文件），仅当前用户可读写。托管供应商凭据存为 <code>credentials/&lt;name&gt;.json</code>，MCP server 凭据存在 <code>credentials/mcp/</code> 子目录下。凭据写入使用原子流程（tmp → fsync → rename）防止写损。</li></ul><h2 id="会话数据" tabindex="-1">会话数据 <a class="header-anchor" href="#会话数据" aria-label="Permalink to “会话数据”">​</a></h2><p>每个会话的数据存在 <code>sessions/&lt;workDirKey&gt;/&lt;sessionId&gt;/</code> 下，同时在顶层 <code>session_index.jsonl</code> 里维护一份索引（每行一条记录，含 <code>sessionId</code>、<code>sessionDir</code>、<code>workDir</code> 三个字段）。<code>workDirKey</code> 是从工作目录路径生成的桶名，格式为 <code>wd_&lt;slug&gt;_&lt;sha256前12位&gt;</code>。</p><p>会话目录内部包含：</p><ul><li><strong><code>state.json</code></strong>：会话标题、<code>lastPrompt</code>、创建/更新时间、<code>forkedFrom</code> 等元数据。</li><li><strong><code>upcoming-goals.json</code></strong>：由 <code>/goal next &lt;objective&gt;</code> 创建的 TUI 专属队列。它不属于 Agent 对话；只有当前目标完成并提升后续目标后，才会进入 Agent 对话。</li><li><strong><code>agents/main/wire.jsonl</code></strong>：主 Agent 的完整通信记录，用于会话恢复和回放。</li><li><strong><code>agents/main/plans/</code></strong>：Plan 模式下写入的计划文件，按计划 id 命名（<code>&lt;id&gt;.md</code>）。</li><li><strong><code>agents/agent-0/</code> 等</strong>：子 Agent 实例目录，各自含 <code>wire.jsonl</code>。</li><li><strong><code>logs/kimi-code.log</code></strong>：该会话的诊断日志，只有发生诊断事件时才存在。</li><li><strong><code>tasks/</code></strong>：后台任务持久化——<code>tasks/&lt;task_id&gt;.json</code> 保存状态/pid/退出码，<code>tasks/&lt;task_id&gt;/output.log</code> 保存输出。</li><li><strong><code>cron/</code></strong>：定时任务持久化，用 <code>kimi --session</code> 恢复会话时重新加载到调度器。详见<a href="/code/docs/kimi-code-cli/reference/tools.html#定时任务">定时任务</a>。</li></ul><h2 id="内置工具缓存" tabindex="-1">内置工具缓存 <a class="header-anchor" href="#内置工具缓存" aria-label="Permalink to “内置工具缓存”">​</a></h2><p><code>Grep</code> 工具第一次需要 ripgrep 时，CLI 可自动下载 <code>rg</code> 并缓存到 <code>bin/rg</code>（Windows 为 <code>bin/rg.exe</code>）。终端界面的文件引用补全使用 <code>fd</code>；需要时 CLI 会在后台自动下载并缓存到 <code>bin/fd</code>（Windows 为 <code>bin/fd.exe</code>）。之后的运行会直接复用缓存的二进制。<code>rg</code> 优先使用系统 <code>PATH</code>，再使用缓存；<code>fd</code> 优先检查托管缓存，再回退到系统 <code>fd</code> / <code>fdfind</code>。删除 <code>bin/</code> 目录会在下次需要时触发重新下载。</p><h2 id="日志与更新状态" tabindex="-1">日志与更新状态 <a class="header-anchor" href="#日志与更新状态" aria-label="Permalink to “日志与更新状态”">​</a></h2><ul><li><strong><code>logs/kimi-code.log</code></strong>（全局）：记录启动、登录、导出等跨会话事件。</li><li><strong><code>&lt;sessionDir&gt;/logs/kimi-code.log</code></strong>（会话级）：记录单个会话内的诊断事件。</li></ul><p>报 bug 时，优先用 <code>kimi export</code> 导出相关会话（详见 <a href="/code/docs/kimi-code-cli/reference/kimi-command.html">kimi 命令</a>）；会话日志默认包含在导出包里。不想分享全局日志时加 <code>--no-include-global-log</code>。</p><p><code>updates/</code> 下的文件（<code>latest.json</code>、<code>install.json</code>、<code>install.lock</code>、<code>rollout.log</code>）由自动更新机制维护，通常无需手动编辑。<code>rollout.log</code> 记录每次更新检查命中的灰度分批情况，可用于排查设备何时能收到新版本。</p><h2 id="输入历史" tabindex="-1">输入历史 <a class="header-anchor" href="#输入历史" aria-label="Permalink to “输入历史”">​</a></h2><p>终端输入历史按工作目录分开保存，路径为 <code>user-history/&lt;md5(workDir)&gt;.jsonl</code>。用于在终端界面里用方向键浏览历史提示词。</p><h2 id="清理数据" tabindex="-1">清理数据 <a class="header-anchor" href="#清理数据" aria-label="Permalink to “清理数据”">​</a></h2><p>删除数据根目录（<code>~/.kimi-code/</code> 或 <code>KIMI_CODE_HOME</code> 指定路径）可清除所有运行时数据。只需清理部分内容时：</p><table tabindex="0"><thead><tr><th>需求</th><th>操作</th></tr></thead><tbody><tr><td>重置配置</td><td>删除 <code>~/.kimi-code/config.toml</code></td></tr><tr><td>重置终端界面偏好</td><td>删除 <code>~/.kimi-code/tui.toml</code></td></tr><tr><td>清理所有会话</td><td>删除 <code>~/.kimi-code/sessions/</code> 和 <code>session_index.jsonl</code></td></tr><tr><td>清理诊断日志</td><td>删除 <code>~/.kimi-code/logs/</code></td></tr><tr><td>清理输入历史</td><td>删除 <code>~/.kimi-code/user-history/</code></td></tr><tr><td>重置更新状态</td><td>删除 <code>~/.kimi-code/updates/latest.json</code></td></tr><tr><td>强制重新下载托管 <code>rg</code> 和 <code>fd</code></td><td>删除 <code>~/.kimi-code/bin/</code></td></tr><tr><td>清除供应商 OAuth 登录态</td><td>运行 <code>/logout</code>，或删除对应的 <code>credentials/&lt;name&gt;.json</code></td></tr><tr><td>清除 MCP server OAuth 登录态</td><td>删除 <code>credentials/mcp/</code>（<code>/logout</code> 不会清理 MCP 凭据）</td></tr><tr><td>移除用户级 MCP 声明</td><td>删除 <code>$KIMI_CODE_HOME/mcp.json</code>（默认为 <code>~/.kimi-code/mcp.json</code>）</td></tr><tr><td>清理全局 Kimi 专属 Agent 指令</td><td>删除 <code>$KIMI_CODE_HOME/AGENTS.md</code>（默认为 <code>~/.kimi-code/AGENTS.md</code>）</td></tr><tr><td>清理 plugin 安装记录</td><td>删除 <code>$KIMI_CODE_HOME/plugins/</code>（本地 plugin 源码不受影响）</td></tr><tr><td>清空 Kimi 专属用户级 Skills</td><td>删除 <code>$KIMI_CODE_HOME/skills/</code>（默认为 <code>~/.kimi-code/skills/</code>）</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/configuration/config-files.html">配置文件</a> — <code>config.toml</code> 各字段的完整说明</li><li><a href="/code/docs/kimi-code-cli/configuration/env-vars.html">环境变量</a> — <code>KIMI_CODE_HOME</code> 等路径变量的详细用法</li></ul>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};